{
  "name": {
    "en": "Contact Us Form",
    "ar": "نموذج تواصل معنا"
  },
  "description": {
    "en": "Simple contact form without steps",
    "ar": "نموذج تواصل بسيط بدون خطوات"
  },
  "has_steps": false,
  "fields": [
    {
      "name": { "en": "Full Name", "ar": "الاسم الكامل" },
      "scheme": {
        "input_type": "text",
        "rules": ["required", "string", "min:2", "max:100"]
      }
    },
    {
      "name": { "en": "Email Address", "ar": "البريد الإلكتروني" },
      "scheme": {
        "input_type": "email",
        "rules": ["required", "email", "max:255"]
      }
    },
    {
      "name": { "en": "Phone Number", "ar": "رقم الهاتف" },
      "scheme": {
        "input_type": "tel",
        "rules": ["nullable", "regex:/^[0-9]{10,15}$/"]
      }
    },
    {
      "name": { "en": "Subject", "ar": "الموضوع" },
      "scheme": {
        "input_type": "select",
        "rules": ["required", "in:general,support,billing,other"],
        "reference": {
          "type": "enum",
          "options": [
            { "value": "general",  "label": { "en": "General Inquiry", "ar": "استفسار عام" } },
            { "value": "support",  "label": { "en": "Technical Support", "ar": "دعم فني" } },
            { "value": "billing",  "label": { "en": "Billing", "ar": "الفوترة" } },
            { "value": "other",    "label": { "en": "Other", "ar": "أخرى" } }
          ]
        }
      }
    },
    {
      "name": { "en": "Message", "ar": "الرسالة" },
      "scheme": {
        "input_type": "textarea",
        "rules": ["required", "string", "min:10", "max:1000"]
      }
    },
    {
      "name": { "en": "Attachment", "ar": "مرفق" },
      "scheme": {
        "input_type": "file",
        "rules": ["nullable", "file", "mimes:pdf,doc,docx,jpg,png", "max:5120"],
        "html_attributes": { "accept": ".pdf,.doc,.docx,.jpg,.png" }
      }
    },
    {
      "name": { "en": "Subscribe to Newsletter", "ar": "الاشتراك في النشرة الإخبارية" },
      "scheme": {
        "input_type": "checkbox",
        "rules": ["nullable", "boolean"],
        "reference": { "type": "boolean" }
      }
    }
  ]
}

